#![allow(dead_code)]
use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Json {
    Null,
    Bool(bool),
    Int(i64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    pub fn get(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Obj(kv) => kv.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    pub fn str_(&self) -> &str {
        match self {
            Json::Str(s) => s,
            o => panic!("expected a string, got {}", o),
        }
    }
    pub fn string(&self) -> String {
        self.str_().to_string()
    }
    pub fn int_(&self) -> i64 {
        match self {
            Json::Int(n) => *n,
            o => panic!("expected an integer, got {}", o),
        }
    }
    pub fn i32_(&self) -> i32 {
        self.int_() as i32
    }
    pub fn u32_(&self) -> u32 {
        self.int_() as u32
    }
    pub fn u8_(&self) -> u8 {
        self.int_() as u8
    }
    pub fn bool_(&self) -> bool {
        match self {
            Json::Bool(b) => *b,
            o => panic!("expected a bool, got {}", o),
        }
    }
    pub fn arr(&self) -> &Vec<Json> {
        match self {
            Json::Arr(a) => a,
            o => panic!("expected an array, got {}", o),
        }
    }
    pub fn list<T>(&self, f: &dyn Fn(&Json) -> T) -> Vec<T> {
        self.arr().iter().map(|x| f(x)).collect()
    }
}

impl fmt::Display for Json {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Json::Null => write!(f, "null"),
            Json::Bool(b) => write!(f, "{}", b),
            Json::Int(n) => write!(f, "{}", n),
            Json::Str(s) => {
                write!(f, "\"")?;
                for c in s.chars() {
                    match c {
                        '"' => write!(f, "\\\"")?,
                        '\\' => write!(f, "\\\\")?,
                        '\n' => write!(f, "\\n")?,
                        '\t' => write!(f, "\\t")?,
                        c if (c as u32) < 0x20 => write!(f, "\\u{:04x}", c as u32)?,
                        c => write!(f, "{}", c)?,
                    }
                }
                write!(f, "\"")
            }
            Json::Arr(a) => {
                write!(f, "[")?;
                for (i, x) in a.iter().enumerate() {
                    if i > 0 {
                        write!(f, ",")?;
                    }
                    write!(f, "{}", x)?;
                }
                write!(f, "]")
            }
            Json::Obj(kv) => {
                write!(f, "{{")?;
                for (i, (k, v)) in kv.iter().enumerate() {
                    if i > 0 {
                        write!(f, ",")?;
                    }
                    write!(f, "{}:{}", Json::Str(k.clone()), v)?;
                }
                write!(f, "}}")
            }
        }
    }
}

struct Parser {
    s: Vec<char>,
    i: usize,
}

pub fn parse(src: &str) -> Result<Json, String> {
    let mut p = Parser { s: src.chars().collect(), i: 0 };
    let v = p.value()?;
    p.ws();
    if p.i != p.s.len() {
        return Err("trailing data".to_string());
    }
    Ok(v)
}

impl Parser {
    fn ws(&mut self) {
        while self.i < self.s.len() && self.s[self.i].is_whitespace() {
            self.i += 1;
        }
    }
    fn lit(&mut self, word: &str, v: Json) -> Result<Json, String> {
        let w: Vec<char> = word.chars().collect();
        if self.s[self.i..].starts_with(&w) {
            self.i += w.len();
            Ok(v)
        } else {
            Err(format!("bad literal at {}", self.i))
        }
    }
    fn value(&mut self) -> Result<Json, String> {
        self.ws();
        match self.s.get(self.i).copied() {
            None => Err("unexpected end".to_string()),
            Some('n') => self.lit("null", Json::Null),
            Some('t') => self.lit("true", Json::Bool(true)),
            Some('f') => self.lit("false", Json::Bool(false)),
            Some('"') => Ok(Json::Str(self.string()?)),
            Some('[') => {
                self.i += 1;
                let mut out = Vec::new();
                self.ws();
                if self.s.get(self.i) == Some(&']') {
                    self.i += 1;
                    return Ok(Json::Arr(out));
                }
                loop {
                    out.push(self.value()?);
                    self.ws();
                    match self.s.get(self.i) {
                        Some(',') => self.i += 1,
                        Some(']') => {
                            self.i += 1;
                            return Ok(Json::Arr(out));
                        }
                        _ => return Err(format!("bad array at {}", self.i)),
                    }
                }
            }
            Some('{') => {
                self.i += 1;
                let mut out = Vec::new();
                self.ws();
                if self.s.get(self.i) == Some(&'}') {
                    self.i += 1;
                    return Ok(Json::Obj(out));
                }
                loop {
                    self.ws();
                    let k = self.string()?;
                    self.ws();
                    if self.s.get(self.i) != Some(&':') {
                        return Err(format!("expected ':' at {}", self.i));
                    }
                    self.i += 1;
                    let v = self.value()?;
                    out.push((k, v));
                    self.ws();
                    match self.s.get(self.i) {
                        Some(',') => self.i += 1,
                        Some('}') => {
                            self.i += 1;
                            return Ok(Json::Obj(out));
                        }
                        _ => return Err(format!("bad object at {}", self.i)),
                    }
                }
            }
            Some(c) if c == '-' || c.is_ascii_digit() => {
                let st = self.i;
                self.i += 1;
                while self.i < self.s.len() && self.s[self.i].is_ascii_digit() {
                    self.i += 1;
                }
                let t: String = self.s[st..self.i].iter().collect();
                t.parse::<i64>().map(Json::Int).map_err(|e| format!("{}: {}", t, e))
            }
            Some(c) => Err(format!("unexpected {:?} at {}", c, self.i)),
        }
    }
    fn hex4(&mut self) -> Result<u32, String> {
        if self.i + 4 > self.s.len() {
            return Err("short \\u escape".to_string());
        }
        let t: String = self.s[self.i..self.i + 4].iter().collect();
        self.i += 4;
        u32::from_str_radix(&t, 16).map_err(|e| e.to_string())
    }
    fn string(&mut self) -> Result<String, String> {
        if self.s.get(self.i) != Some(&'"') {
            return Err(format!("expected string at {}", self.i));
        }
        self.i += 1;
        let mut out = String::new();
        loop {
            let c = *self.s.get(self.i).ok_or("unterminated string")?;
            self.i += 1;
            match c {
                '"' => return Ok(out),
                '\\' => {
                    let e = *self.s.get(self.i).ok_or("bad escape")?;
                    self.i += 1;
                    match e {
                        '"' => out.push('"'),
                        '\\' => out.push('\\'),
                        '/' => out.push('/'),
                        'b' => out.push('\u{8}'),
                        'f' => out.push('\u{c}'),
                        'n' => out.push('\n'),
                        'r' => out.push('\r'),
                        't' => out.push('\t'),
                        'u' => {
                            let mut cp = self.hex4()?;
                            if (0xD800..0xDC00).contains(&cp) {
                                if self.s.get(self.i) == Some(&'\\') && self.s.get(self.i + 1) == Some(&'u') {
                                    self.i += 2;
                                    let lo = self.hex4()?;
                                    cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                } else {
                                    return Err("lone surrogate".to_string());
                                }
                            }
                            out.push(char::from_u32(cp).ok_or("bad code point")?);
                        }
                        _ => return Err(format!("bad escape \\{}", e)),
                    }
                }
                c => out.push(c),
            }
        }
    }
}

start.tests/test_main.c:
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "byte_stuff.h"

static int failures = 0;
static int total = 0;

static void fail(const char *label, const char *msg) {
    failures++;
    if (failures <= 8) printf("  %s: %s\n", label, msg);
}

static void check_err(const char *label, int rc) {
    total++;
    if (rc == 0) fail(label, "expected an error");
}

static void check_str(const char *label, int rc, const char *got, const char *want) {
    total++;
    char msg[600];
    if (rc != 0) { fail(label, "unexpected error"); return; }
    if (strcmp(got, want) != 0) {
        snprintf(msg, sizeof msg, "want \"%s\", got \"%s\"", want, got);
        fail(label, msg);
    }
}

static void check_int(const char *label, int rc, int64_t got, int64_t want) {
    total++;
    char msg[200];
    if (rc != 0) { fail(label, "unexpected error"); return; }
    if (got != want) {
        snprintf(msg, sizeof msg, "want %lld, got %lld", (long long) want, (long long) got);
        fail(label, msg);
    }
}

int main(void) {
    {  uint8_t out = 0; int rc = byte_stuff_checksum("0102", &out); check_int("checksum#0", rc, (int64_t) out, INT64_C(5)); }
    {  char out[8192]; int rc = byte_stuff_frame("0102", out, sizeof out); check_str("frame#1", rc, out, "7e0102057f"); }
    {  char out[8192]; int rc = byte_stuff_frame("7e", out, sizeof out); check_str("frame#2", rc, out, "7e7d5e7d5f7f"); }
    {  char out[8192]; int rc = byte_stuff_unstuff("017d5e02", out, sizeof out); check_str("unstuff#3", rc, out, "017e02"); }
    {  char out[8192]; int rc = byte_stuff_unframe("7e0102057f", out, sizeof out); check_str("unframe#4", rc, out, "0102"); }
    {  int64_t out = 0; int rc = byte_stuff_count_frames("7e6162c57f007e6364c97f", &out); check_int("count_frames#5", rc, (int64_t) out, INT64_C(2)); }
    {  uint8_t out = 0; int rc = byte_stuff_checksum("", &out); check_int("checksum#6", rc, (int64_t) out, INT64_C(0)); }
    {  char out[8192]; int rc = byte_stuff_frame("", out, sizeof out); check_str("frame#7", rc, out, "7e007f"); }
    if (failures) {
        printf("%d of %d vectors failed\n", failures, total);
        return 1;
    }
    printf("ok %d vectors\n", total);
    return 0;
}

