FLAG, END, ESC = 0x7E, 0x7F, 0x7D
_HEX = "0123456789abcdefABCDEF"


def _parse(text):
    if len(text) % 2 or any(c not in _HEX for c in text):
        raise ValueError("bad hex")
    return bytes(int(text[i:i + 2], 16) for i in range(0, len(text), 2))


def _hex(b):
