#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "byte_stuff.h"

static int failures = 0;
static int total = 0;

static void fail(const char *label, const char *msg) {
    failures++;
    if (failures <= 8) printf("  %s: %s\n", label, msg);
}

static void check_err(const char *label, int rc) {
    total++;
    if (rc == 0) fail(label, "expected an error");
}

static void check_str(const char *label, int rc, const char *got, const char *want) {
    total++;
    char msg[600];
    if (rc != 0) { fail(label, "unexpected error"); return; }
    if (strcmp(got, want) != 0) {
        snprintf(msg, sizeof msg, "want \"%s\", got \"%s\"", want, got);
        fail(label, msg);
    }
}

static void check_int(const char *label, int rc, int64_t got, int64_t want) {
    total++;
    char msg[200];
    if (rc != 0) { fail(label, "unexpected error"); return; }
    if (got != want) {
        snprintf(msg, sizeof msg, "want %lld, got %lld", (long long) want, (long long) got);
        fail(label, msg);
    }
}

int main(void) {
    {  uint8_t out = 0; int rc = byte_stuff_checksum("0102", &out); check_int("checksum#0", rc, (int64_t) out, INT64_C(5)); }
    {  char out[8192]; int rc = byte_stuff_frame("0102", out, sizeof out); check_str("frame#1", rc, out, "7e0102057f"); }
    {  char out[8192]; int rc = byte_stuff_frame("7e", out, sizeof out); check_str("frame#2", rc, out, "7e7d5e7d5f7f"); }
    {  char out[8192]; int rc = byte_stuff_unstuff("017d5e02", out, sizeof out); check_str("unstuff#3", rc, out, "017e02"); }
    {  char out[8192]; int rc = byte_stuff_unframe("7e0102057f", out, sizeof out); check_str("unframe#4", rc, out, "0102"); }
    {  int64_t out = 0; int rc = byte_stuff_count_frames("7e6162c57f007e6364c97f", &out); check_int("count_frames#5", rc, (int64_t) out, INT64_C(2)); }
    {  uint8_t out = 0; int rc = byte_stuff_checksum("", &out); check_int("checksum#6", rc, (int64_t) out, INT64_C(0)); }
    {  char out[8192]; int rc = byte_stuff_frame("", out, sizeof out); check_str("frame#7", rc, out, "7e007f"); }
    if (failures) {
        printf("%d of %d vectors failed\n", failures, total);
        return 1;
    }
    printf("ok %d vectors\n", total);
    return 0;
}

